css:
/* Sakura Glass: dusk-sky glow behind frosted panes */
[data-workspace-area="conversation"] {
  background:
    radial-gradient(ellipse 70% 55% at 85% 0%, rgba(245,163,199,0.22), transparent 60%),
    radial-gradient(ellipse 60% 50% at 0% 100%, rgba(156,207,216,0.16), transparent 60%),
    radial-gradient(ellipse 50% 40% at 40% 55%, rgba(196,167,231,0.12), transparent 70%),
    linear-gradient(160deg, #1b1630 0%, #14121f 55%, #0f1420 100%) !important;
}
.messages-timeline-scroll { background: transparent !important; }

/* Frosted header */
[data-chat-header] {
  background: rgba(20,18,31,0.45) !important;
  backdrop-filter: blur(18px) saturate(140%);
  -webkit-backdrop-filter: blur(18px) saturate(140%);
  border-bottom: 1px solid rgba(255,255,255,0.06) !important;
}

/* Your messages: glass bubble, monospace like a neovim buffer */
[data-user-message-bubble] {
  background: linear-gradient(135deg, rgba(245,163,199,0.16), rgba(196,167,231,0.10)) !important;
  backdrop-filter: blur(14px);
  -webkit-backdrop-filter: blur(14px);
  border: 1px solid rgba(245,163,199,0.22) !important;
  box-shadow: 0 4px 24px rgba(0,0,0,0.25), inset 0 1px 0 rgba(255,255,255,0.06);
  font-family: "JetBrains Mono", "SF Mono", Menlo, monospace;
  font-size: 0.92em;
}

/* Code blocks: darker glass */
.chat-markdown-codeblock {
  background: rgba(15,13,24,0.62) !important;
  backdrop-filter: blur(10px);
  -webkit-backdrop-filter: blur(10px);
  border: 1px solid rgba(196,167,231,0.14) !important;
}

/* Composer: floating glass card with a soft sakura glow on focus */
[data-slot="composer-host"] {
  background: rgba(26,22,40,0.55) !important;
  backdrop-filter: blur(20px) saturate(150%);
  -webkit-backdrop-filter: blur(20px) saturate(150%);
  border: 1px solid rgba(255,255,255,0.08) !important;
  box-shadow: 0 8px 32px rgba(0,0,0,0.35), inset 0 1px 0 rgba(255,255,255,0.05);
  transition: box-shadow .2s, border-color .2s;
}
[data-slot="composer-host"]:focus-within {
  border-color: rgba(245,163,199,0.40) !important;
  box-shadow: 0 8px 32px rgba(0,0,0,0.35), 0 0 0 1px rgba(245,163,199,0.18), 0 0 28px rgba(245,163,199,0.12);
}
.composer-tiptap { font-family: "JetBrains Mono", "SF Mono", Menlo, monospace; }

/* Popups: frosted */
[data-slot="menu-popup"], [data-slot="popover-popup"], [data-slot="dialog-popup"], [data-slot="tooltip-popup"] {
  background: rgba(22,19,34,0.78) !important;
  backdrop-filter: blur(20px) saturate(140%);
  -webkit-backdrop-filter: blur(20px) saturate(140%);
  border: 1px solid rgba(255,255,255,0.08) !important;
}

/* Sidebar: active row gets a sakura edge, like a neovim cursorline */
[data-thread-item][aria-current="page"], [data-thread-item][data-active="true"] {
  box-shadow: inset 2px 0 0 #f5a3c7;
}

/* Thin lavender scrollbars */
::-webkit-scrollbar { width: 8px; height: 8px; }
::-webkit-scrollbar-thumb { background: rgba(196,167,231,0.22); border-radius: 8px; }
::-webkit-scrollbar-thumb:hover { background: rgba(196,167,231,0.38); }
[data-slot="scroll-area-thumb"] { background: rgba(196,167,231,0.28) !important; }

svg.lucide { stroke-width: 1.75; }
